from decimal import Decimal, ROUND_HALF_UP
from typing import Any


def _value(row: dict, key: str) -> Any:
    return row.get(key, "")


def _fixed(value: Any, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def _is_empty(value: Any) -> bool:
    return value is None or value == ""


def _zpad_cents(value: Any, width: int) -> str:
    if _is_empty(value):
        value = 0
    cents = (Decimal(str(value)) * Decimal("100")).quantize(
        Decimal("1"), rounding=ROUND_HALF_UP
    )
    return f"{int(cents):0{width}d}"


def format_account(row: dict) -> str:
    ann_rev = _value(row, "ANN_REV")
    cred_hold = _value(row, "CRED_HOLD")
    create_dt = _value(row, "CREATE_DT")

    if _is_empty(cred_hold):
        cred_hold = "N"
    if _is_empty(create_dt):
        create_dt = "00000000"

    return (
        _fixed(_value(row, "ACCT_ID"), 10)
        + _fixed(_value(row, "ACCT_NM"), 40)
        + _fixed(_value(row, "REGION_CD"), 3)
        + _zpad_cents(ann_rev, 15)
        + str(cred_hold)
        + str(create_dt)
    )
